def maxProductPairWithSum(nums: list[int], target: int) -> int:
    seen = set()
    best_product = float('-inf')

    for x in nums:
        comp = target - x
        if comp in seen:
            best_product = max(best_product, x * comp)
        seen.add(x)

    return best_product if best_product != float('-inf') else -1

#include <vector>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    long long maxProductPairWithSum(std::vector<int>& nums, int target) {
        std::unordered_set<int> seen;
        long long best = -1e18;

        for (int x : nums) {
            int comp = target - x;
            if (seen.count(comp)) {
                best = std::max(best, (long long)x * comp);
            }
            seen.insert(x);
        }
        return best == -1e18 ? -1 : best;
    }
};

import java.util.*;

class Solution {
    public long maxProductPairWithSum(int[] nums, int target) {
        Set<Integer> seen = new HashSet<>();
        long best = (long)-1e18;

        for (int x : nums) {
            int comp = target - x;
            if (seen.contains(comp)) {
                best = Math.max(best, (long) x * comp);
            }
            seen.add(x);
        }
        return best == (long)-1e18 ? -1 : best;
    }
}

